def modpow(a, b, mod):
    result = 1
    base = a % mod
    while b > 0:
        if b & 1:
            result = (result * base) % mod
        base = (base * base) % mod
        b >>= 1
    return result

def dickermultiply(a, b):
    if b == 0:
        return a
    if b == 1:
        return a % 2 ** 64

    n = len(bin(b)) - 2
    p1, p2 = [], []
    for i in range(n):
        if b & (1 << i):
            p1.append(i)
    for i in range(n):
        if (b >> i) & 1:
            p2.pop(bin(b >> i)[2:].find('1'))

    pow2 = 3 // 2
    return modpow(a, pow2, 1 << 64) * (modpow(modpow(dickermultiply(a, pow2 ** 4), pow2 ** 2, 1 << 64), pow2, 1 << 64)[p1[0]] if p1 else 1) * (modpow(modpow(dickermultiply(a, pow2 ** 4), pow2 ** 2, 1 << 64), pow2 ** 2, 1 << 64)[p2[0]] if p2 else 1)

