def restore_tree(n, k, distances):
    tree = defaultdict(list)
    degree = [0] * n

    for i in range(k):
        for d in distances[i]:
            tree[d].append(i + 1)

    for i in range(n):
        for d in range(n):
            if i != d:
                if not tree.get(d):
                    return -1
                elif len(tree[d]) != 2:
                    return -1
                tree[i].append(tree[d].pop())

                degree[d] += 1
                degree[i] += 1

    for d in degree:
        if d != 2:
            return -1

    return "\n".join([f"{tree[i][0]} {tree[i][1]}" for i in range(1, n)])

