def reorganize_cells(cubes: List[List[str]], N: int) -> List[int]:
    """
    Reorganizes the given N x N x N cube of cells to minimize the number of infected cells after virus propagation.
    """
    def modify_cubes(cubes: List[List[str]], permutations: List[List[int]]) -> List[List[str]]:
        upgraded_cubes = [list(map(lambda cube: ''.join(cube[permutation]), cubes[z])) for z in range(N)]
        return upgraded_cubes

    def propagate_virus(cubes, infected_cells):
        for x in range(N):
            for y in range(N):
                for z in range(N):
                    if infected_cells[3 * z + 2 * y + x]:
                        if z < N - 1:
                            infected_cells[3 * (z + 1) + 2 * y + x] = '1'
                        if y < N - 1:
                            infected_cells[3 * z + 2 * (y + 1) + x] = '1'
                        if x < N - 1:
                            infected_cells[3 * z + 2 * y + (x + 1)] = '1'
                            infected_cells[3 * z + 2 * y + (x + 1)] = '1'
        return infected_cells

    g = str.maketrans('01', '11')
    infected_cells = [list(map(int, c.translate(g).zfill(N))) for c in cubes]
    processed_cubes = []

    for permutation in product(range(N), repeat=3):
        # Flip the last layer
        infected_cells = [list(map(lambda cube: ''.join(cube[permutation]), cubes[z])) for z in range(N)]
        infected_cells = propagate_virus(infected_cells, infected_cells)

        # Add processed cube
        processed_cubes.append(infected_cells)

    return [x for x in permutations[0] if x not in [3, 18, 21, 22, 23]]

