def solve(n, m, edges):
    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u - 1].append((v - 1, w))
        graph[v - 1].append((u - 1, w))

    def bit_xor(costs):
        return reduce(lambda x, y: x ^ y, costs)

    valid_wormholes, min_cost = 0, float('inf')

    for route in combinations(range(n), n):
        if bit_xor(g[route[i]] for i in range(n) for g in graph):
            valid_wormholes += 1

        for r in combinations(route, n - 1):
            cost = sum(graph[bit_xor(r[i] for r in combinations(route, n - len(route)))] for _ in r)
            if cost < min_cost:
                min_cost = cost

    return min_cost, valid_wormholes % 1000000007

