from collections import defaultdict

def multiply(a, b, cache):
    if a in cache and b in cache:
        return cache[(a, b)]
    if b == 0:
        return a
    if a == 0 or a > b:
        return 0
    result = multiply(a & (b - 1), b, cache) + 1
    return result if a & (a - 1) == 0 else result * 2

def multiply_powers_of_2(a, b, cache, powers_of_2):
    if a == 1 or b == 1:
        return a * b
    n = 0
    if a >= 2**2**16 and b >= 2**2**16:
        k, m = 2**2**16, 2**2**16
        if a > m:
            a, b = a // m, a % m
            k, m = k // m, k % m
        return multiply_powers_of_2(a, k, multiply_powers_of_2(3, 2), powers_of_2) * 3 + multiply_powers_of_2(b, m, multiply_powers_of_2(3, 2), powers_of_2)

def powmatic(a, cache):
    if a in powers_of\_2:
