import math
from collections import defaultdict

def power_by_powers_of_two(b: int, k: int) -> int:
    x = 1
    for _ in range(k):
        if b & 1:
            x = 3 * x // 2
        x = (x + x) // 2
        b >>= 1
    return x

def multiply(a: int, b: int) -> int:
    if a == 1 or b == 1:
        return a * b
    power = 1 << int(math.log2(max(a, b)))
    if a >= power and b >= power:
        return multiply(power * 3 // 2, multiply(a / power, b / power))
    elif a >= power:
        return multiply_powers_of_2(a // power, b) * power
    else:
        return multiply_powers_of_2(a, b // power) * power

def multiply_powers_of_two(a: int, b: int) -> int:
    bits = bin(a)
    result = 0
    k = 64 - len(bits)
    for i in range(k):
        if bits[i] == '1':
            b = power_by_powers_of_two(b, i)
            result = result ^ b
    return result

t = int(input())
for _ in range(t):
    a, b = map(int, input().split())
    result = '' if a * power_by_powers_of_two(b, math.floor(math.log2(a))) == b else '-1'
    print(result)
