    points.sort()

    # Initialize condupts to all points and the minimum operations to 0
    checks = {point for point in points} 
    moves = 0

    for point in points:
        # If the current point has not been checked yet, add it to the condupts and reset moves counter
        if checks.discard(point) == 0:
            checks = {point}
            moves = 0
        # Count operations needed to move the point to a checkpoint
        for cpoint in checks:
            dist = abs(point[0] - cpoint[0]) + abs(point[1] - cpoint[1])
            if dist <= c:
                moves += min(dist, c - dist)
                break

    print(len(checks), moves)
