from bisect import bisect_left, bisect_right

def almost_increasing_product_count(arr):
    n = len(arr)
    dp = [0] * n
    increasing = True

    for i in range(1, n):
        if i < n - 1 and arr[i] <= arr[i + 1]:
            if increasing:
                dp[i] = 1 + dp[i-2]
            else:
                dp[i] = 1
            increasing = False
        elif not increasing and arr[i] >= arr[i + 1]:
            increasing = True

        if not increasing:
            dp[i] += 2
        elif increasing and arr[i] == arr[i-1]:
            dp[i] = dp[i-1] + 1
        else:
            dp[i] = dp[i-1]

    return min(dp[i] for i in range(len(arr)))

input_n = int(input())
input_arr = list(map(int, input().split()))

print(almost_increasing_product_count(input_arr))
